    /// <summary>
    /// Coc for insert
    /// </summary>
    public void insert()
    {
        METWMSOrderTrans    metWMSOrderTrans;
        next insert();

        /*Bug 303922 - CB797 - CW Weight not calculating Pricing and sales order line not updated with weight - start*/
        this.metUpdateCWActualWeightSalesLine();
        /*Bug 303922 - CB797 - CW Weight not calculating Pricing and sales order line not updated with weight - end*/

        metWMSOrderTrans    =   this.metWMSOrderTrans();
        this.metPackMETWMSOrderTrans(metWMSOrderTrans);
        this.SysExtensionSerializerMap::postInsert();
    }

    /// <summary>
    /// Coc for update
    /// </summary>
    public void update()
    {
        METWMSOrderTrans    metWMSOrderTrans;
        WMSOrderTrans       wmsOrderTrans = this.orig();

        METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
        next update();
        
        metWMSOrderTrans    =   this.metWMSOrderTrans();
        if (!METWMSOrderTrans.WMSOrderTrans)
        {
            this.metPackMETWMSOrderTrans(metWMSOrderTrans);
        }
        // Bug 188764: CB387 - Picklist Registration - Quantity field not updating
        // Moved to custom batch job after the picklist registration line is completed
        // this.metShortPickDeliveryReminderUpd(this, wmsOrderTrans);

        ttsbegin;
        select firstonly RecId from metSalesOrderShipmentLoadLines
            where metSalesOrderShipmentLoadLines.WMSOrderTransRecId == this.RecId;

        if (metSalesOrderShipmentLoadLines.RecId)
        {
            update_recordset metSalesOrderShipmentLoadLines
                setting PickedQty = this.qty
                    where metSalesOrderShipmentLoadLines.WMSOrderTransRecId == this.RecId;
        }
        ttscommit;

        /*Bug 303922 - CB797 - CW Weight not calculating Pricing and sales order line not updated with weight - start*/
        if (this.qty != wmsOrderTrans.qty)
        {
            this.metUpdateCWActualWeightSalesLine();
        }
        /*Bug 303922 - CB797 - CW Weight not calculating Pricing and sales order line not updated with weight - end*/

        //BUG 298479 - CB238 - NDC & Int xDock warehouse processing; Canceclled transfer order lines are showing in the transfer order finalisation screen.
        if(wmsOrderTrans.qty == 0.00
            && InventTransferTable::find(wmsOrderTrans.inventTransRefId).RecId)
        {
            this.propcessCancelledTOLines(wmsOrderTrans);
        }
        //BUG 298479 - CB238 - NDC & Int xDock warehouse processing; Canceclled transfer order lines are showing in the transfer order finalisation screen.

        this.SysExtensionSerializerMap::postUpdate();
    }

    /// <summary>
    /// Change status
    /// </summary>
    public void changeStatus(WMSExpeditionStatus _newStatus)
    {
        next changeStatus(_newStatus);

        // CB679 - Backorder processes for NDC & CSD
        this.metChangeOrderExtractStatus();
    }

    /// <summary>
    /// Change Order Extract status
    /// </summary>
    private void metChangeOrderExtractStatus()
    {
        if (this.inventTransType == InventTransType::Sales)
        {
            SalesLine salesLine = SalesLine::findInventTransId(this.inventTransId);
            METSalesLine metSalesLine = salesLine.metSalesLine();
            SalesTable salesTable = salesLine.salesTable();
            InventLocation inventLocation = InventLocation::find(salesTable.InventLocationId);

            if (salesTable.METAllowBackOrders == NoYes::Yes && 
               inventLocation.METCSDWarehouse == NoYes::Yes && 
               inventLocation.METWaveRequired == NoYes::Yes)
            {
                METOrderExtractStatus orderExtractStatusUpdate = metSalesLine.OrderExtractStatus;
                
                METWMSOrderTrans metWMSOrderTrans = METWMSOrderTrans::find(this.RecId);
                if (metWMSOrderTrans)
                {
                    // Open - if picking list is partially registered
                    if (metWMSOrderTrans.qtyOrig > this.qty)
                    {
                        orderExtractStatusUpdate = METOrderExtractStatus::Open;
                    }
                    // Extracted - if picking list is fully registered
                    else if (metWMSOrderTrans.qtyOrig == this.qty)
                    {
                        orderExtractStatusUpdate = METOrderExtractStatus::Extracted;
                    }
                }

                if (orderExtractStatusUpdate != metSalesLine.OrderExtractStatus)
                {
                
                    ttsbegin;

                    metSalesLine.selectForUpdate(true);
                    metSalesLine.OrderExtractStatus = orderExtractStatusUpdate;
                    metSalesLine.update();

                    salesTable.selectForUpdate(true);
                    salesTable.metUpdateExtractStatus();

                    ttscommit;
                }
            }
        }
    }

/// <summary>
/// Find corresponding METWMSOrderTrans record
/// </summary>
/// <returns>METWMSOrderTrans record</returns>
public METWMSOrderTrans metWMSOrderTrans()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METWMSOrderTrans));
}

    /// <summary>
    /// pack the METWMSOrderTrans record fields
    /// </summary>
    /// <param name = "_metWMSOrderTrans">Record buffer of METWMSOrderTrans to pack</param>
    public void metPackMETWMSOrderTrans(METWMSOrderTrans _metWMSOrderTrans)
    {
        SalesLine               salesLine;

        _metWMSOrderTrans.WMSOrderTrans = this.RecId;

        // Bug 188764: CB387 - Picklist Registration - Quantity field not updating
        // initialise qtyOrig when WMSOrderTrans is inserted
        _metWMSOrderTrans.qtyOrig = this.qty;

        //update cases, weight and volume when it's for sales line
        salesLine = SalesLine::findInventTransId(this.inventTransId);
        if(salesLine.RecId)
        {
            [_metWMSOrderTrans.ShipCaseQty, _metWMSOrderTrans.ReservedQty, _metWMSOrderTrans.Weight, _metWMSOrderTrans.volume] = SalesLine::metGetQtyWeightVolume(this.qty, this.itemId, salesLine.inventDim());
        }
        // CB715_TransferOrderExtract
        // Calculate weight and volume based on picked/reserved qty and save it in table
        else if (_metWMSOrderTrans.wmsOrderTrans().inventTransType == InventTransType::TransferOrderShip)
        {
            METInventTransferLine metInventTransferLine = InventTransferLine::findTransIdShip(this.inventTransId).metInventTransferLine();

            if (metInventTransferLine && metInventTransferLine.ShipCaseQty)
            {
                WMSPickingLineQty convertedQty = _metWMSOrderTrans.wmsOrderTrans().qty / metInventTransferLine.ShipCaseQty;

                _metWMSOrderTrans.volume = convertedQty * metInventTransferLine.TOUnitVolume;
                _metWMSOrderTrans.Weight = convertedQty * metInventTransferLine.TOUnitWeight;
            }
        }

        this.SysExtensionSerializerMap::packExtensionTable(_metWMSOrderTrans);
    }

    /// <summary>
    /// picking list registration - short picked
    /// </summary>
    public void metShortPickDeliveryReminderUpd()
    {
        SalesLine           salesLine;
        InventDim           inventDim;
        SalesTable          salesTable;
        SalesUpdateRemain   salesUpdateRemain;
        METWMSOrderTrans    metWMSOrderTrans    = METWMSOrderTrans::find(this.RecId);
        InventTransferLine  inventTransferLine  = InventTransferLine::findTransIdShip(this.inventTransId, true);

        switch (this.inventTransType)
        {
            //If the sales order is not a back order and the sales line is short picked i.e the picked quantity from dallas
            //is less than the pick quantity in D365 FO, system to automatically reduce the delivery remainder of the sales line by short-picked quantity
            case InventTransType::Sales:
                if (metWMSOrderTrans.qtyOrig > this.qty)
                {
                    //update cases, weight and volume when it's for sales line
                    salesLine   = SalesLine::findInventTransId(this.inventTransId);
                    inventDim   = InventDim::find(salesLine.InventDimId);
                    salesTable  = salesLine.salesTable();

                    if (salesLine.METReplenishmentPOReference != '')
                    {
                        METSalesOrderProcessHelper salesProcessHelper = new METSalesOrderProcessHelper();
                        salesProcessHelper.updateIntercompanyPOAndConfirm(salesLine, this.qty);
                    }
                    if (salesTable.METAllowBackOrders == NoYes::No)
                    {
                        ttsbegin;
                        salesLine.selectForUpdate(true);
                        
                        SalesUpdateRemain metSalesUpdateRemain = SalesUpdateRemain::construct();

                        metSalesUpdateRemain.metUpdateDeliverRemainder(salesLine,
                                    EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                    salesLine.ItemId,
                                    salesLine.InventDimId,
                                    this.qty,
                                    this.UnitId(),
                                    salesLine.SalesUnit,
                                    NoYes::Yes),
                                    this.qty,
                                    this.pdsCWQty);
                        ttscommit;
                        
                        if (SalesTable::find(salesTable.InterCompanyOriginalSalesId))
                        {
                            //Change the company to the original company of the intercompany sales order.
                            changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
                            {
                                SalesLine           interCompanySalesLine;
                                SalesUpdateRemain   metInterCompanySalesUpdateRemain;

                                interCompanySalesLine = METSalesOrderProcessHelper::
                                    getInterCompanySalesLine(salesTable.InterCompanyOriginalSalesId, salesLine, inventDim);

                                if (interCompanySalesLine.RecId != 0)
                                {
                                    ttsbegin;
                                    interCompanySalesLine.selectForUpdate(true);
                        
                                    metInterCompanySalesUpdateRemain = SalesUpdateRemain::construct();
                        
                                    metInterCompanySalesUpdateRemain.metUpdateDeliverRemainder(interCompanySalesLine,
                                        EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                        interCompanySalesLine.ItemId,
                                        interCompanySalesLine.InventDimId,
                                        this.qty,
                                        this.UnitId(),
                                        interCompanySalesLine.SalesUnit,
                                        NoYes::Yes),
                                        this.qty,
                                        this.pdsCWQty);
                                    ttscommit;
                                }
                            }
                        }
                    }
                }
            case InventTransType::TransferOrderShip:
                //Transfer order delivery reminder reduced to Dallas picking qty if it is less then Transfer order picking qty
                //Transfer order is not backorder
                if (inventTransferLine.QtyTransfer > this.qty)
                {
                    ttsbegin;
                    inventTransferLine.selectForUpdate(true);
                    
                    InventTransferTable         inventTransferTable     = inventTransferLine.inventTransferTable();
                    METInventTransferTableExt   inventTransferTableExt  = inventTransferTable.metInventTransferTableExt();
                    METInventTransferLine       metInventTransferLine   = inventTransferLine.metInventTransferLine();

                    if (!inventTransferTableExt.AllowBackorder)
                    {
                        inventTransferLine.QtyRemainShip = this.qty;
                        inventTransferLine.PdsCWQtyRemainShip = this.PdsCWQty;
                        inventTransferLine.updateDeliverRemainder(); //std code contains ttsbegin and ttscommit

                        if (inventTransferLine.displayQtyReservedPhysical() == 0)
                        {
                            select firstonly METAllowBackOrders from salesTable
                            join salesLine
                                where salesTable.SalesId == salesLine.SalesId
                                && salesLine.InventTransId == metInventTransferLine.SalesLineTransId;

                            if (!salesTable.METAllowBackOrders)
                            {
                                ttsbegin;
                                salesLine.selectForUpdate(true);
                                SalesUpdateRemain::construct().updateDeliverRemainder(salesLine, 0, 0, 0);
                                ttscommit;
                            }
                        }

                        if (metInventTransferLine.SalesId && metInventTransferLine.SalesLineTransId)
                        {
                            SalesLine       salesLineLocal      = SalesLine::findInventTransId(metInventTransferLine.SalesLineTransId);
                            SalesTable      salesTableLocal     = salesLineLocal.salesTable();
                            METSalesLine    metSalesLineLocal   = salesLineLocal.metSalesLine();

                            if (salesTableLocal.METAllowBackOrders == NoYes::No
                                && metSalesLineLocal.OrderExtractStatus == METOrderExtractStatus::Extracted)
                            {
                                SalesUpdateRemain metSalesUpdateRemain = SalesUpdateRemain::construct();
                                
                                metSalesUpdateRemain.metUpdateDeliverRemainder(salesLineLocal,
                                                    EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                                    salesLineLocal.ItemId,
                                                    salesLineLocal.InventDimId,
                                                    this.qty,
                                                    this.UnitId(),
                                                    salesLineLocal.SalesUnit,
                                                    NoYes::Yes),
                                                    this.qty,
                                                    this.pdsCWQty);
                            }
                        }
                    }
                    ttscommit;
                }
                break;
            default:
                return;
        }
    }

/// <summary>
/// Get line number from sales order
/// </summary>
/// <returns>Line number</returns>
[SysClientCacheDataMethodAttribute(true)]
public display LineNum lineNum()
{
    return SalesLine::findInventTransId(this.inventTransId).LineNum;
}

    /// <summary>
    /// Bug 303922 - CB797 - CW Weight not calculating Pricing and sales order line not updated with weight.
    /// Updates CWActualWeight on salesline.
    /// </summary>
    private void metUpdateCWActualWeightSalesLine()
    {
        WMSOrderTrans wmsOrderTrans;
        METSalesLine  metSalesLine;
        SalesLine     salesLine;

        if (this.inventTransType != InventTransType::Sales || !PdsGlobal::pdsIsCWItem(this.itemId))
        {
            return;
        }

        select sum(qty) from wmsOrderTrans
            where wmsOrderTrans.inventTransId == this.inventTransId;;

        update_recordset salesLine
            setting METCWActualWeight = wmsOrderTrans.qty
                    && salesLine.InventTransId == this.inventTransId;

    }

    public void propcessCancelledTOLines(WMSOrderTrans  _orderTrans)
    {
        #OCCRetryCount

        InventTransferTable             inventTransferTable;
        METInventTransferTableExt       metInventTransferTableExt;
        InventTransferLine              inventTransferLine;
        METInventTransferLine           metInventTransferLine;
        SalesTable                      salesTable;
        SalesLine                       salesLine;
        METSalesLine                    metSalesLine;

        try
        {
            ttsbegin;

            this.removeLineFromShipmentAndLoad(_orderTrans);

            metInventTransferTableExt = METInventTransferTableExt::findByTransferId(_orderTrans.inventTransRefId);

            select firstonly * from metInventTransferLine
                exists join inventTransferLine
                    where inventTransferLine.InventTransId == _orderTrans.inventTransId
                        && inventTransferLine.TransferId == _orderTrans.inventTransRefId
                        && metInventTransferLine.InventTransferLine == inventTransferLine.RecId;

            if (metInventTransferLine.SalesId != ''
                    && (metInventTransferTableExt.TransferType == MetCrossdocKTransferType::CrossDock
                    || metInventTransferTableExt.TransferType == MetCrossdocKTransferType::CSD))
            {
                salesLine = salesLine::findInventTransId(metInventTransferLine.SalesLineTransId,true);

                if(SalesTable::find(metInventTransferLine.SalesId).METAllowBackOrders == NoYes::Yes)
                {
                    if (salesLine.inventTable().pdsCWItem())
                    {
                        SalesUpdateRemain::construct().updateCatchWeightDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        SalesUpdateRemain::construct().updateDeliverRemainder(salesLine, 0, 0);
                    }
                }
                else
                {
                    metSalesLine = METSalesLine::find(salesLine.RecId, true);
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Open;
                    metSalesLine.update();
                }
            }
            else
            {
                if(metInventTransferTableExt.TransferType == MetCrossdocKTransferType::None
                    || metInventTransferTableExt.TransferType == MetCrossdocKTransferType::CSD)
                {
                    if(metInventTransferTableExt.AllowBackorder == NoYes::Yes)
                    {
                        metInventTransferLine.selectForUpdate(true);
                        metInventTransferLine.OrderExtractStatus = METOrderExtractStatus::Open;
                        metInventTransferLine.update();
                    }
                }
            }
        
            ttscommit;  
        }
        catch(Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

    public void removeLineFromShipmentAndLoad(WMSOrderTrans _orderTrans)
    {
        METSalesOrderShipmentLoadHeader TOShipmentLoadHeader, otherShipmentInLoadExist;
        METSalesOrderShipmentLoadLines  TOShipmentLoadLine, otherTOInShipmentExist;
        WMSOrderTrans                   wmsOrderTransLocal;
        MetShipmentId                   shipmentId;
        MetLoadId                       loadId;

        select firstonly RecId from wmsOrderTransLocal
            where wmsOrderTransLocal.inventTransRefId == _orderTrans.inventTransRefId
                && wmsOrderTransLocal.qty != 0.00;

        if (wmsOrderTransLocal.RecId)
        {
            // Remove only the current line with zero qty
            delete_from TOShipmentLoadLine
                where TOShipmentLoadLine.WMSOrderTransRecId == _orderTrans.RecId;

            return;
        }

        select firstonly forupdate TOShipmentLoadHeader
            join TOShipmentLoadLine
            where TOShipmentLoadHeader.ShipmentId == TOShipmentLoadLine.ShipmentId
                && TOShipmentLoadLine.WMSOrderTransRecId == _orderTrans.RecId;

        shipmentId = TOShipmentLoadHeader.ShipmentId;
        loadId = TOShipmentLoadHeader.LoadId;

        if (strLen(shipmentId) == 0 || strLen(loadId) == 0)
        {
            return;
        }

        // Delete all lines for this TO with qty == 0.00
        delete_from TOShipmentLoadLine
            exists join wmsOrderTransLocal
            where TOShipmentLoadLine.OrderNum == wmsOrderTransLocal.inventTransRefId
                && wmsOrderTransLocal.inventTransRefId == _orderTrans.inventTransRefId
                && wmsOrderTransLocal.qty == 0.00;

        // Check for other TOs in the same shipment
        select firstonly RecId from otherTOInShipmentExist
            where otherTOInShipmentExist.ShipmentId == shipmentId
                && otherTOInShipmentExist.OrderNum != _orderTrans.inventTransRefId;

        // Delete header if no other TOs in shipment.
        if (!otherTOInShipmentExist.RecId)
        {
            TOShipmentLoadHeader.delete();
        }
    }
